const { owner } = trigger.data;
const orgRes = await fetch(`${process.env.AUTH_API_URL}/api/organization/by-slug/${owner}`, {
  headers: { 'Content-Type': 'application/json' }
});
if (!orgRes.ok) return { recipients: [] };
const org = await orgRes.json();
const membersRes = await fetch(`${process.env.AUTH_API_URL}/api/organization/members?orgId=${org.id}`, {
  headers: { 'Content-Type': 'application/json' }
});
if (!membersRes.ok) return { recipients: [] };
const { data: members } = await membersRes.json();
const owners = members.filter(m => m.role === 'owner');
return { recipients: owners.map(m => m.user.email) };

const { recipients } = steps['resolve-owners'].output;
if (!recipients || recipients.length === 0) return { sent: 0 };

const { service, project, phase, image, commit, owner } = trigger.data;
const eventType = trigger.type;

let templateId;
if (eventType.includes('build.failed')) templateId = 'build-failed';
else if (eventType.includes('deploy.succeeded')) templateId = 'deploy-succeeded';
else if (eventType.includes('service.crashed')) templateId = 'service-crashed';
else return { sent: 0, reason: 'unknown event type' };

const fractalUrl = `${process.env.FRACTAL_APP_URL}/workspaces/${owner}/projects/${project}/services/${service}`;
const templateData = { serviceName: service, projectName: project, commitSha: commit, fractalUrl, imageTag: image?.split(':').pop() };

let sent = 0;
for (const email of recipients) {
  const suppRes = await fetch(process.env.VORTEX_API_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${process.env.VORTEX_API_KEY}` },
    body: JSON.stringify({ query: `query($email:String!){emailSuppressions(condition:{email:$email}){totalCount}}`, variables: { email } })
  });
  const suppJson = await suppRes.json();
  if ((suppJson.data?.emailSuppressions?.totalCount ?? 0) > 0) continue;

  const renderRes = await fetch(`${process.env.FRACTAL_APP_URL}/api/email/render`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${process.env.EMAIL_RENDER_SECRET}` },
    body: JSON.stringify({ templateId, templateData })
  });
  if (!renderRes.ok) continue;
  const { html, subject } = await renderRes.json();

  const sendRes = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${process.env.RESEND_API_KEY}` },
    body: JSON.stringify({ from: process.env.SENDER_EMAIL_ADDRESS || 'notifications@omni.dev', to: [email], subject: `${subject} - ${service}`, html })
  });
  if (sendRes.ok) sent++;
}
return { sent };
